import {
  PlaneGeometry,
  MeshBasicNodeMaterial,
  TextureNode,
  vec2,
  uv,
  mul,
  add,
  uniform,
  float,
  noise,
  timerGlobal,
  Mesh,
  Object3D,
} from 'three/webgpu';
import { texture } from 'three/tsl';

/**
 * Creates a static collection card with an engineered gradient surface and subtle grain.
 * The card is a textured plane using the provided image, positioned as specified.
 * No interactive behavior or data bindings are applied.
 *
 * @param {NodeConfig} config - Configuration provided by the framework.
 * @param {NodeContext} ctx - Context with texture loader and other utilities.
 * @returns {THREE.Object3D} The card mesh with cleanup and handler placeholders.
 */
export default function createNode(config, ctx) {
  // ---- Geometry ----
  // Use the atlas region aspect ratio (512:320 = 1.6) as the plane proportions.
  const aspect = 512 / 320;
  const geometry = new PlaneGeometry(aspect, 1);

  // ---- Texture ----
  // Load the provided image via the cached texture loader.
  const imgUrl = '/prism-mock/home/nodes/orb-decor.png';
  const texNode = texture(ctx.textureLoader.load(imgUrl));

  // ---- Material ----
  // Add subtle grain using TSL noise for the "subtle grain" effect described.
  const grainStrength = uniform(0.012);
  const grain = mul(
    noise(mul(uv(), vec2(800, 800))),
    grainStrength
  );
  const colorWithGrain = add(texNode, grain);
  const material = new MeshBasicNodeMaterial({ colorNode: colorWithGrain });

  // ---- Mesh ----
  const mesh = new Mesh(geometry, material);
  mesh.position.set(0, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // ---- Handlers (none required) ----
  mesh.userData.handlers = {};

  // ---- Cleanup ----
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // The texture is also owned by the material, so disposing the material is sufficient.
    // However, if needed, we can also dispose the texture node's source.
    if (texNode && texNode.source) {
      texNode.source.data?.dispose?.();
    }
  };

  return mesh;
}
